<?php
$bookings=[];$email=filter_var(trim((string)($_POST['email']??$_SESSION['booking_email']??'')),FILTER_VALIDATE_EMAIL);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if($email){$_SESSION['booking_email']=$email;$q=db()->prepare('SELECT b.*,t.depart_at,r.train_code,a.name origin,c.name destination,(SELECT GROUP_CONCAT(seat_code SEPARATOR ", ") FROM booking_seats WHERE booking_id=b.id) seats FROM bookings b JOIN trips t ON t.id=b.trip_id JOIN routes r ON r.id=t.route_id JOIN stations a ON a.id=r.from_station_id JOIN stations c ON c.id=r.to_station_id WHERE b.email=? ORDER BY b.created_at DESC');$q->execute([$email]);$bookings=$q->fetchAll();}}
?>
<section class="page-banner"><div class="container"><p class="eyebrow">YOUR JOURNEYS, IN ONE PLACE</p><h1>My <em>tickets.</em></h1><p>Look up reservations using the email address from booking.</p></div></section><section class="container content-section"><form method="post" class="lookup-form"><?= csrf_field() ?><label>Email address<input type="email" name="email" required maxlength="190" value="<?= h($_SESSION['booking_email']??'') ?>" placeholder="you@example.com"></label><button class="button primary">Find my bookings →</button></form><?php if($_SERVER['REQUEST_METHOD']==='POST'&&$email&&!$bookings): ?><div class="empty-state"><h3>No bookings found</h3><p>Check the email address used to make the reservation.</p></div><?php endif; ?><?php foreach($bookings as $b): ?><article class="booking-row"><div class="booking-row-main"><span class="train-icon">↗</span><div><small><?= h($b['reference']) ?> · <?= h(date('D, d M Y',strtotime($b['depart_at']))) ?></small><h3><?= h($b['origin']) ?> <span>→</span> <?= h($b['destination']) ?></h3><small><?= h($b['train_code']) ?> · Seats <?= h($b['seats']) ?></small></div></div><span class="pill <?= $b['status']==='confirmed'?'green':'gray' ?>"><?= h($b['status']) ?></span><strong><?= money((float)$b['total_fare']) ?></strong><a class="button secondary small" href="?download=<?= (int)$b['id'] ?>">Download ticket</a><a class="text-link" href="?page=manage">Manage →</a></article><?php endforeach; ?></section>
